  select coalesce(jsonb_agg(jsonb_build_object('id', y."id", 'taskId', y."task_id", 'description', y."description", 'quantity', y."quantity", 'unit', y."unit", 'estimate', y."estimate", 'rank', y."rank") order by y."rank", y."id"), '[]'::jsonb)
