  from (
    select row_number() over () as n, to_jsonb(x) || jsonb_build_object('budget_amount', x."budget_amount"::text) || jsonb_build_object('progress', (
      select case when count(*) = 0 then null else round(100.0 * count(*) filter (where y."state" = 'completed') / count(*) filter (where y."state" <> 'canceled')) end
      from "better_supabase"."tasks" y where y."project_id" = x."id" and y."archived_at" is null
    )) as j, jsonb_build_array((x."created_at")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."projects" x
      where x."tenant_id" = page_projects.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or x."status"::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."owner_id" = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::uuid[]))
        and (coalesce(nullif(coalesce(v_filters #>> '{archived,0}', v_filters ->> 'archived'), '') = 'true', false) or x."archived_at" is null)
        and (v_search is null or x."name" ilike v_search or x."key" ilike v_search)
        and (v_after is null or (x."created_at" <= (v_after ->> 0)::timestamptz and ((x."created_at" < (v_after ->> 0)::timestamptz) or (x."created_at" = (v_after ->> 0)::timestamptz and x."id" > (v_after ->> 1)::uuid))))
      order by x."created_at" desc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  end if;
  if not v_paged then
    return v_items;
  end if;
  if coalesce((v_filters ->> 'total')::boolean, false) then
    select count(*) into v_total from (
      select 1 from "better_supabase"."projects" x
      where x."tenant_id" = page_projects.tenant
        and (not (v_filters -> 'status' is not null and jsonb_typeof(v_filters -> 'status') <> 'null' and not (jsonb_typeof(v_filters -> 'status') = 'array' and jsonb_array_length(v_filters -> 'status') = 0)) or x."status"::text = any((case when jsonb_typeof(v_filters -> 'status') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'status')) else array[v_filters ->> 'status'] end)::text[]))
        and (not (v_filters -> 'ownerId' is not null and jsonb_typeof(v_filters -> 'ownerId') <> 'null' and not (jsonb_typeof(v_filters -> 'ownerId') = 'array' and jsonb_array_length(v_filters -> 'ownerId') = 0)) or x."owner_id" = any((case when jsonb_typeof(v_filters -> 'ownerId') = 'array' then array(select jsonb_array_elements_text(v_filters -> 'ownerId')) else array[v_filters ->> 'ownerId'] end)::uuid[]))
        and (coalesce(nullif(coalesce(v_filters #>> '{archived,0}', v_filters ->> 'archived'), '') = 'true', false) or x."archived_at" is null)
        and (v_search is null or x."name" ilike v_search or x."key" ilike v_search)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$$;
revoke execute on function "better_supabase"."page_projects"(uuid, jsonb) from public, anon;
grant execute on function "better_supabase"."page_projects"(uuid, jsonb) to authenticated, service_role;

-- One project the caller can read, or null.
create or replace function "better_supabase"."get_project"(project uuid)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select to_jsonb(x) || jsonb_build_object('budget_amount', x."budget_amount"::text) || jsonb_build_object('progress', (
      select case when count(*) = 0 then null else round(100.0 * count(*) filter (where y."state" = 'completed') / count(*) filter (where y."state" <> 'canceled')) end
      from "better_supabase"."tasks" y where y."project_id" = x."id" and y."archived_at" is null
    )) from "better_supabase"."projects" x where x."id" = get_project.project
$$;
revoke execute on function "better_supabase"."get_project"(uuid) from public, anon;
grant execute on function "better_supabase"."get_project"(uuid) to authenticated, service_role;


-- Creates an iteration (a cycle or a sprint) or changes it: name, teamId,
-- startsOn, endsOn.
create or replace function "better_supabase"."save_iteration"(tenant uuid, iteration uuid, attrs jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid := save_iteration.iteration;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', save_iteration.tenant, 'tasks.manage'), false)) then
    raise exception 'not allowed to manage projects and iterations' using errcode = '42501', hint = 'TASK_FORBIDDEN';
  end if;
  begin
    if v_id is null then
      insert into "better_supabase"."iterations" ("tenant_id", "team_id", "name", "starts_on", "ends_on")
      values (save_iteration.tenant, (save_iteration.attrs ->> 'teamId')::uuid, save_iteration.attrs ->> 'name',
        (save_iteration.attrs ->> 'startsOn')::date, (save_iteration.attrs ->> 'endsOn')::date)
      returning "id" into v_id;
    else
      update "better_supabase"."iterations" x set
        "name" = coalesce(save_iteration.attrs ->> 'name', x."name"),
        "starts_on" = coalesce((save_iteration.attrs ->> 'startsOn')::date, x."starts_on"),
        "ends_on" = coalesce((save_iteration.attrs ->> 'endsOn')::date, x."ends_on")
      where x."id" = v_id and x."tenant_id" = save_iteration.tenant;
      if not found then
        raise exception 'iteration not found' using errcode = 'P0002', hint = 'TASK_ITERATION_NOT_FOUND';
      end if;
    end if;
  exception when check_violation or not_null_violation then
    raise exception 'an iteration needs a name and ends on or after it starts' using errcode = '22023', hint = 'TASK_ITERATION_INVALID';
  end;
  return (select to_jsonb(x) from "better_supabase"."iterations" x where x."id" = v_id);
end;
$$;
revoke execute on function "better_supabase"."save_iteration"(uuid, uuid, jsonb) from public, anon;
grant execute on function "better_supabase"."save_iteration"(uuid, uuid, jsonb) to authenticated, service_role;


-- Who is acting, as { kind, name } for events and timelines. kind is the
-- profile's own (a short lowercase word), agent when the token's act claim says
-- so, service, system without a user, or user. It labels; no check reads it.
create or replace function "better_supabase"."task_actor"(profile jsonb default null)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'kind', case
      when task_actor.profile ->> 'kind' ~ '^[a-z][a-z_-]{0,31}$' then task_actor.profile ->> 'kind'
      when auth.jwt() -> 'act' ->> 'kind' = 'agent' then 'agent'
      when auth.role() = 'service_role' then 'service'
      when auth.uid() is null then 'system'
      else 'user' end,
    'name', left(coalesce(nullif(task_actor.profile ->> 'name', ''), auth.jwt() -> 'act' ->> 'name'), 120))
$$;
revoke execute on function "better_supabase"."task_actor"(jsonb) from public, anon;
grant execute on function "better_supabase"."task_actor"(jsonb) to authenticated, service_role;


-- Creates a plan of tasks in one transaction. items is a list of attrs for
-- create_task, each with an optional key, assignees and needs. parentId and
-- each needs entry are a task id or { "key": ... } naming another item of the
-- plan. At most 100 items. Returns { tasks, keys }.
create or replace function "better_supabase"."create_tasks"(tenant uuid, items jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item jsonb;
  v_pos integer := 0;
  v_keys jsonb := '{}';
  v_ids uuid[] := '{}';
  v_key text;
  v_task jsonb;
  v_id uuid;
  v_ref jsonb;
  v_prereqs uuid[];
  v_known text[] := array['key', 'title', 'body', 'parentId', 'teamId', 'projectId', 'iterationId', 'priority', 'estimate', 'progress', 'startAt', 'endAt', 'dueAt', 'pipelineId', 'stageId', 'fields', 'assignees', 'needs'];
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if jsonb_typeof(create_tasks.items) is distinct from 'array' then
    raise exception 'items must be a list of tasks' using errcode = '22023', hint = 'TASK_PLAN_INVALID';
  end if;
  if jsonb_array_length(create_tasks.items) > 100 then
    raise exception 'a plan holds at most 100 tasks' using errcode = '54000', hint = 'TASK_PLAN_TOO_LARGE';
  end if;
  for v_item in select value from jsonb_array_elements(create_tasks.items) loop
    v_pos := v_pos + 1;
    if jsonb_typeof(v_item) is distinct from 'object' then
      raise exception 'each item must be an object' using errcode = '22023', hint = 'TASK_PLAN_INVALID';
    end if;
    if exists (select 1 from jsonb_object_keys(v_item) k where not (k = any (v_known))) then
      raise exception 'an item has a property create can''t write' using errcode = '22023', hint = 'TASK_PLAN_INVALID';
    end if;
    v_key := v_item ->> 'key';
    if v_key is not null then
      if v_keys ? v_key then
        raise exception 'two items share a key' using errcode = '22023', hint = 'TASK_PLAN_INVALID';
      end if;
      v_keys := v_keys || jsonb_build_object(v_key, v_pos);
    end if;
  end loop;
  for v_item in select value from jsonb_array_elements(create_tasks.items) loop
    for v_ref in select value from jsonb_array_elements(coalesce(v_item -> 'needs', '[]'::jsonb)) union all select v_item -> 'parentId' where v_item ? 'parentId' loop
      if jsonb_typeof(v_ref) = 'object' and not (v_keys ? (v_ref ->> 'key')) then
        raise exception 'an item refers to a key the plan doesn''t have' using errcode = '22023', hint = 'TASK_PLAN_INVALID';
      end if;
    end loop;
    if v_item ? 'needs' then
      raise exception 'needs takes the relations block' using errcode = '22023', hint = 'TASK_NEEDS_UNSUPPORTED';
    end if;
  end loop;
  for v_item in select value from jsonb_array_elements(create_tasks.items) loop
    v_task := "better_supabase"."create_task"(
      create_tasks.tenant,
      (v_item - 'key' - 'needs' - 'assignees' - 'parentId'),
      coalesce(array(select x::uuid from jsonb_array_elements_text(coalesce(v_item -> 'assignees', '[]'::jsonb)) x), '{}'));
    v_ids := array_append(v_ids, (v_task ->> 'id')::uuid);
  end loop;
  v_pos := 0;
  for v_item in select value from jsonb_array_elements(create_tasks.items) loop
    v_pos := v_pos + 1;
    v_id := v_ids[v_pos];
    if v_item ? 'parentId' then
      v_ref := v_item -> 'parentId';
      update "better_supabase"."tasks" x set "parent_id" = case when jsonb_typeof(v_ref) = 'object' then v_ids[(v_keys ->> (v_ref ->> 'key'))::integer] else (v_ref #>> '{}')::uuid end
      where x."id" = v_id;
    end if;
  end loop;
  return jsonb_build_object(
    'tasks', coalesce((select jsonb_agg(to_jsonb(x) || jsonb_build_object('number', x."number"::text) || jsonb_build_object('assignees', coalesce((select jsonb_agg(ra."user_id" order by ra."created_at", ra."user_id") from "better_supabase"."task_assignees" ra where ra."task_id" = x."id"), '[]'::jsonb)) || jsonb_build_object('checklist', (select jsonb_build_object('total', count(*), 'done', count(*) filter (where rk."done")) from "better_supabase"."task_checklist_items" rk where rk."task_id" = x."id")) || jsonb_build_object('claim', "better_supabase"."task_claim"(x."id")) order by array_position(v_ids, x."id")) from "better_supabase"."tasks" x where x."id" = any (v_ids)), '[]'::jsonb),
    'keys', coalesce((select jsonb_object_agg(k.key, v_ids[(k.value #>> '{}')::integer]) from jsonb_each(v_keys) k), '{}'::jsonb));
end;
$$;
revoke execute on function "better_supabase"."create_tasks"(uuid, jsonb) from public, anon;
grant execute on function "better_supabase"."create_tasks"(uuid, jsonb) to authenticated, service_role;



-- Takes the lease on a task. Returns { task, claim } with the claim's token,
-- which renew and release need. A live claim of someone else raises
-- TASK_CLAIMED; the same holder claiming again keeps the token. A task that
-- waits on prerequisites raises TASK_NOT_READY (with the needs option), a held
-- one TASK_HELD, a closed one TASK_CLOSED.
create or replace function "better_supabase"."claim_task"(task uuid, lease integer default null, profile jsonb default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row "better_supabase"."tasks";
  v_claim "better_supabase"."task_claims";
  v_actor jsonb := "better_supabase"."task_actor"(claim_task.profile);
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."tasks" x where x."id" = claim_task.task and x."archived_at" is null for update;
  if not found then
    raise exception 'no such work item' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'tasks.write'), false)) then
    raise exception 'not allowed to change this work item' using errcode = '42501', hint = 'TASK_FORBIDDEN';
  end if;
  if v_row."closed_at" is not null then
    raise exception 'a closed task can''t be claimed' using errcode = '55000', hint = 'TASK_CLOSED';
  end if;
  if v_row."held_at" is not null then
    raise exception 'the task is on hold' using errcode = '55000', hint = 'TASK_HELD';
  end if;
  insert into "better_supabase"."task_claims" as c ("task_id", "tenant_id", "holder_id", "profile", "expires_at")
  values (v_row."id", v_row."tenant_id", auth.uid(), v_actor, now() + make_interval(secs => least(900, greatest(1, coalesce(claim_task.lease, 900)))))
  on conflict ("task_id") do update set
    "token" = case when c."expires_at" > now() then c."token" else gen_random_uuid() end,
    "epoch" = case when c."expires_at" > now() then c."epoch" else c."epoch" + 1 end,
    "holder_id" = excluded."holder_id",
    "profile" = excluded."profile",
    "claimed_at" = case when c."expires_at" > now() then c."claimed_at" else now() end,
    "expires_at" = excluded."expires_at",
    "expired_at" = null
  where not c."expires_at" > now()
    or (c."holder_id" is not distinct from excluded."holder_id" and c."profile" ->> 'name' is not distinct from excluded."profile" ->> 'name')
  returning * into v_claim;
  if not found then
    raise exception 'another holder has a live claim on the task' using errcode = '55P03', hint = 'TASK_CLAIMED';
  end if;
  null;
  return jsonb_build_object('task', (select to_jsonb(x) || jsonb_build_object('number', x."number"::text) || jsonb_build_object('assignees', coalesce((select jsonb_agg(ra."user_id" order by ra."created_at", ra."user_id") from "better_supabase"."task_assignees" ra where ra."task_id" = x."id"), '[]'::jsonb)) || jsonb_build_object('checklist', (select jsonb_build_object('total', count(*), 'done', count(*) filter (where rk."done")) from "better_supabase"."task_checklist_items" rk where rk."task_id" = x."id")) || jsonb_build_object('claim', "better_supabase"."task_claim"(x."id")) from "better_supabase"."tasks" x where x."id" = v_row."id"), 'claim', jsonb_build_object('token', v_claim."token", 'epoch', v_claim."epoch", 'holderId', v_claim."holder_id", 'profile', v_claim."profile", 'claimedAt', v_claim."claimed_at", 'expiresAt', v_claim."expires_at"));
end;
$$;
revoke execute on function "better_supabase"."claim_task"(uuid, integer, jsonb) from public, anon;
grant execute on function "better_supabase"."claim_task"(uuid, integer, jsonb) to authenticated, service_role;

-- Claims the next ready task of a tenant: assigned to you first, then the
-- oldest. filter narrows the pick: teamId, projectId, parentId, stageId,
-- assigneeId. Concurrent callers skip each other's rows. Raises
-- TASK_NOTHING_READY when no task qualifies.
create or replace function "better_supabase"."claim_next_task"(tenant uuid, filter jsonb default null, lease integer default null, profile jsonb default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', claim_next_task.tenant, 'tasks.write'), false)) then
    raise exception 'not allowed to claim work items' using errcode = '42501', hint = 'TASK_FORBIDDEN';
  end if;
  select x."id" into v_id from "better_supabase"."tasks" x
  where x."tenant_id" = claim_next_task.tenant and x."archived_at" is null and x."closed_at" is null
    and x."held_at" is null
    and not exists (select 1 from "better_supabase"."task_claims" c where c."task_id" = x."id" and c."expires_at" > now())
      and (claim_next_task.filter ->> 'teamId' is null or x."team_id" = (claim_next_task.filter ->> 'teamId')::uuid)
      and (claim_next_task.filter ->> 'projectId' is null or x."project_id" = (claim_next_task.filter ->> 'projectId')::uuid)
      and (claim_next_task.filter ->> 'parentId' is null or x."parent_id" = (claim_next_task.filter ->> 'parentId')::uuid)
      and (claim_next_task.filter ->> 'stageId' is null or x."stage_id" = (claim_next_task.filter ->> 'stageId')::uuid)
      and (claim_next_task.filter ->> 'assigneeId' is null or exists (select 1 from "better_supabase"."task_assignees" y where y."task_id" = x."id" and y."user_id" = (claim_next_task.filter ->> 'assigneeId')::uuid))
  order by (case when exists (select 1 from "better_supabase"."task_assignees" y where y."task_id" = x."id" and y."user_id" = auth.uid()) then 0 else 1 end), x."number"
  limit 1
  for update of x skip locked;
  if v_id is null then
    raise exception 'no task is ready to claim' using errcode = 'P0002', hint = 'TASK_NOTHING_READY';
  end if;
  return "better_supabase"."claim_task"(v_id, claim_next_task.lease, claim_next_task.profile);
end;
$$;
revoke execute on function "better_supabase"."claim_next_task"(uuid, jsonb, integer, jsonb) from public, anon;
grant execute on function "better_supabase"."claim_next_task"(uuid, jsonb, integer, jsonb) to authenticated, service_role;

-- Extends a live claim to now plus the lease. Raises TASK_CLAIM_LOST when the
-- token isn't the live claim's, because the lease ran out or someone took over.
create or replace function "better_supabase"."renew_task_claim"(task uuid, token uuid, lease integer default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_claim "better_supabase"."task_claims";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  update "better_supabase"."task_claims" c set "expires_at" = now() + make_interval(secs => least(900, greatest(1, coalesce(renew_task_claim.lease, 900))))
  where c."task_id" = renew_task_claim.task and c."token" = renew_task_claim.token and c."expires_at" > now()
    and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', c."tenant_id", 'tasks.write'), false))
  returning * into v_claim;
  if not found then
    raise exception 'the claim ran out or another holder took over' using errcode = '55000', hint = 'TASK_CLAIM_LOST';
  end if;
  return jsonb_build_object('token', v_claim."token", 'epoch', v_claim."epoch", 'holderId', v_claim."holder_id", 'profile', v_claim."profile", 'claimedAt', v_claim."claimed_at", 'expiresAt', v_claim."expires_at");
end;
$$;
revoke execute on function "better_supabase"."renew_task_claim"(uuid, uuid, integer) from public, anon;
grant execute on function "better_supabase"."renew_task_claim"(uuid, uuid, integer) to authenticated, service_role;

-- Gives a claim up. Raises TASK_CLAIM_NOT_HELD when nobody holds the task and
-- TASK_CLAIM_LOST when the token isn't the live claim's.
create or replace function "better_supabase"."release_task_claim"(task uuid, token uuid, note text default null)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_claim "better_supabase"."task_claims";
  v_row "better_supabase"."tasks";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_claim from "better_supabase"."task_claims" c where c."task_id" = release_task_claim.task for update;
  if not found then
    raise exception 'nobody holds this task' using errcode = 'P0002', hint = 'TASK_CLAIM_NOT_HELD';
  end if;
  if v_claim."token" is distinct from release_task_claim.token or not (v_claim."expires_at" > now()) then
    raise exception 'the claim ran out or another holder took over' using errcode = '55000', hint = 'TASK_CLAIM_LOST';
  end if;
  update "better_supabase"."task_claims" c set "expires_at" = now(), "expired_at" = now() where c."task_id" = release_task_claim.task;
  select * into v_row from "better_supabase"."tasks" x where x."id" = release_task_claim.task;
  null;
  return true;
end;
$$;
revoke execute on function "better_supabase"."release_task_claim"(uuid, uuid, text) from public, anon;
grant execute on function "better_supabase"."release_task_claim"(uuid, uuid, text) to authenticated, service_role;

-- Hands a task to a user: assigns them, notes who delegated, and drops a claim
-- held by someone else. The user needs tasks.read in the organization.
create or replace function "better_supabase"."delegate_task"(task uuid, to_user uuid, profile jsonb default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row "better_supabase"."tasks";
  v_actor jsonb := "better_supabase"."task_actor"(delegate_task.profile);
  v_added boolean;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."tasks" x where x."id" = delegate_task.task and x."archived_at" is null for update;
  if not found then
    raise exception 'no such work item' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'tasks.write'), false)) then
    raise exception 'not allowed to change this work item' using errcode = '42501', hint = 'TASK_FORBIDDEN';
  end if;
  if not coalesce(better_supabase.can_user(delegate_task.to_user, 'tenant', v_row."tenant_id", 'tasks.read'), false) then
    raise exception 'the user can''t read tasks in this organization' using errcode = '22023', hint = 'TASK_DELEGATE_INVALID';
  end if;
  insert into "better_supabase"."task_assignees" ("tenant_id", "task_id", "user_id") values (v_row."tenant_id", v_row."id", delegate_task.to_user)
  on conflict do nothing;
  v_added := found;
  delete from "better_supabase"."task_claims" c where c."task_id" = v_row."id" and c."holder_id" is distinct from delegate_task.to_user;
  update "better_supabase"."tasks" x set "delegate_profile" = v_actor where x."id" = v_row."id";
  null;
  if v_added then
    null;
  end if;
  return (select to_jsonb(x) || jsonb_build_object('number', x."number"::text) || jsonb_build_object('assignees', coalesce((select jsonb_agg(ra."user_id" order by ra."created_at", ra."user_id") from "better_supabase"."task_assignees" ra where ra."task_id" = x."id"), '[]'::jsonb)) || jsonb_build_object('checklist', (select jsonb_build_object('total', count(*), 'done', count(*) filter (where rk."done")) from "better_supabase"."task_checklist_items" rk where rk."task_id" = x."id")) || jsonb_build_object('claim', "better_supabase"."task_claim"(x."id")) from "better_supabase"."tasks" x where x."id" = v_row."id");
end;
$$;
revoke execute on function "better_supabase"."delegate_task"(uuid, uuid, jsonb) from public, anon;
grant execute on function "better_supabase"."delegate_task"(uuid, uuid, jsonb) to authenticated, service_role;

-- Deletes the claims whose lease ran out, moves each task to the expired stage
-- (the claims.expiredStage option) and records task.claim_expired.
create or replace function "better_supabase"."expire_task_claims"()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_claim "better_supabase"."task_claims";
  v_row "better_supabase"."tasks";
  v_count integer := 0;
begin
  for v_claim in update "better_supabase"."task_claims" c set "expired_at" = now() where c."expires_at" <= now() and c."expired_at" is null returning c.* loop
    v_count := v_count + 1;
    select * into v_row from "better_supabase"."tasks" x where x."id" = v_claim."task_id";
    if found and v_row."closed_at" is null then
      null;
    end if;
  end loop;
  return v_count;
end;
$$;
revoke execute on function "better_supabase"."expire_task_claims"() from public, anon, authenticated;
grant execute on function "better_supabase"."expire_task_claims"() to service_role;


-- Puts a task on hold: kind says what it waits for (a short lowercase word),
-- note reaches ask_user_ids through the task's conversation with mentions.
-- A live claim is dropped. Each asked user needs tasks.read.
create or replace function "better_supabase"."hold_task"(task uuid, kind text, note text default null, ask_user_ids uuid[] default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row "better_supabase"."tasks";
  v_stage uuid;
  v_note text := nullif(trim(hold_task.note), '');
  v_ask uuid[] := array(select distinct x from unnest(coalesce(hold_task.ask_user_ids, '{}')) x where x is not null);
  v_conversation text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if hold_task.kind is null or hold_task.kind !~ '^[a-z][a-z_]{0,31}$' then
    raise exception 'kind must be a short lowercase word such as review or input' using errcode = '22023', hint = 'TASK_HOLD_INVALID';
  end if;
  select * into v_row from "better_supabase"."tasks" x where x."id" = hold_task.task and x."archived_at" is null for update;
  if not found then
    raise exception 'no such work item' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'tasks.write'), false)) then
    raise exception 'not allowed to change this work item' using errcode = '42501', hint = 'TASK_FORBIDDEN';
  end if;
  if v_row."closed_at" is not null then
    raise exception 'a closed task can''t be held' using errcode = '55000', hint = 'TASK_CLOSED';
  end if;
  if v_row."held_at" is not null then
    raise exception 'the task is already on hold' using errcode = '55000', hint = 'TASK_HELD';
  end if;
  if exists (select 1 from unnest(v_ask) x where not coalesce(better_supabase.can_user(x, 'tenant', v_row."tenant_id", 'tasks.read'), false)) then
    raise exception 'an asked user can''t read tasks in this organization' using errcode = '22023', hint = 'TASK_HOLD_INVALID';
  end if;
  delete from "better_supabase"."task_claims" c where c."task_id" = v_row."id";
  update "better_supabase"."tasks" x set "held_at" = now(), "hold_kind" = hold_task.kind where x."id" = v_row."id";
  if cardinality(v_ask) > 0 then
    raise exception 'asking people needs the messaging block' using errcode = '22023', hint = 'TASK_HOLD_MESSAGING_MISSING';
  end if;
  select * into v_row from "better_supabase"."tasks" x where x."id" = v_row."id";
  null;
  return (select to_jsonb(x) || jsonb_build_object('number', x."number"::text) || jsonb_build_object('assignees', coalesce((select jsonb_agg(ra."user_id" order by ra."created_at", ra."user_id") from "better_supabase"."task_assignees" ra where ra."task_id" = x."id"), '[]'::jsonb)) || jsonb_build_object('checklist', (select jsonb_build_object('total', count(*), 'done', count(*) filter (where rk."done")) from "better_supabase"."task_checklist_items" rk where rk."task_id" = x."id")) || jsonb_build_object('claim', "better_supabase"."task_claim"(x."id")) from "better_supabase"."tasks" x where x."id" = v_row."id");
end;
$$;
revoke execute on function "better_supabase"."hold_task"(uuid, text, text, uuid[]) from public, anon;
grant execute on function "better_supabase"."hold_task"(uuid, text, text, uuid[]) to authenticated, service_role;

-- Ends a hold. With the hold stage option the task returns to the stage it
-- left.
create or replace function "better_supabase"."release_task_hold"(task uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row "better_supabase"."tasks";
  v_kind text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."tasks" x where x."id" = release_task_hold.task and x."archived_at" is null for update;
  if not found then
    raise exception 'no such work item' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'tasks.write'), false)) then
    raise exception 'not allowed to change this work item' using errcode = '42501', hint = 'TASK_FORBIDDEN';
  end if;
  if v_row."held_at" is null then
    raise exception 'the task isn''t on hold' using errcode = '55000', hint = 'TASK_NOT_HELD';
  end if;
  v_kind := v_row."hold_kind";
  update "better_supabase"."tasks" x set "held_at" = null, "hold_kind" = null, "hold_return_stage_id" = null where x."id" = v_row."id" returning * into v_row;
  null;
  return (select to_jsonb(x) || jsonb_build_object('number', x."number"::text) || jsonb_build_object('assignees', coalesce((select jsonb_agg(ra."user_id" order by ra."created_at", ra."user_id") from "better_supabase"."task_assignees" ra where ra."task_id" = x."id"), '[]'::jsonb)) || jsonb_build_object('checklist', (select jsonb_build_object('total', count(*), 'done', count(*) filter (where rk."done")) from "better_supabase"."task_checklist_items" rk where rk."task_id" = x."id")) || jsonb_build_object('claim', "better_supabase"."task_claim"(x."id")) from "better_supabase"."tasks" x where x."id" = v_row."id");
end;
$$;
revoke execute on function "better_supabase"."release_task_hold"(uuid) from public, anon;
grant execute on function "better_supabase"."release_task_hold"(uuid) to authenticated, service_role;


-- Closes or reopens a task with a note. outcome is completed, canceled, failed
-- or open. stage defaults to the first stage of the matching category in the
-- task's pipeline. failed lands in the canceled category with close reason
-- failed (not_planned where the column can't hold it). The note rides on
-- task.closed, and failed also records task.failed.
create or replace function "better_supabase"."close_task"(task uuid, outcome text, note text default null, stage uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row "better_supabase"."tasks";
  v_stage uuid;
  v_note text := nullif(trim(close_task.note), '');
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if close_task.outcome is null or close_task.outcome not in ('completed', 'canceled', 'failed', 'open') then
    raise exception 'outcome is completed, canceled, failed or open' using errcode = '22023', hint = 'TASK_OUTCOME_INVALID';
  end if;
  select * into v_row from "better_supabase"."tasks" x where x."id" = close_task.task and x."archived_at" is null for update;
  if not found then
    raise exception 'no such work item' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'tasks.write'), false)) then
    raise exception 'not allowed to change this work item' using errcode = '42501', hint = 'TASK_FORBIDDEN';
  end if;
  if close_task.outcome = 'open' and v_row."closed_at" is null then
    return (select to_jsonb(x) || jsonb_build_object('number', x."number"::text) || jsonb_build_object('assignees', coalesce((select jsonb_agg(ra."user_id" order by ra."created_at", ra."user_id") from "better_supabase"."task_assignees" ra where ra."task_id" = x."id"), '[]'::jsonb)) || jsonb_build_object('checklist', (select jsonb_build_object('total', count(*), 'done', count(*) filter (where rk."done")) from "better_supabase"."task_checklist_items" rk where rk."task_id" = x."id")) || jsonb_build_object('claim', "better_supabase"."task_claim"(x."id")) from "better_supabase"."tasks" x where x."id" = v_row."id");
  end if;
  if close_task.outcome <> 'open' and v_row."closed_at" is not null then
    raise exception 'the task is already closed' using errcode = '55000', hint = 'TASK_CLOSED';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_task_close"(uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text)', v_hook::oid::regproc)
        using v_row."id", close_task.outcome, v_note;
    end if;
  end;
  v_stage := coalesce(close_task.stage, case close_task.outcome
    when 'completed' then (select s."id" from "better_supabase"."pipeline_stages" s where s."pipeline_id" = v_row."pipeline_id" and s."category"::text = 'completed' and s."archived_at" is null order by s."rank" collate "C", s."id" limit 1)
    when 'open' then (select s."id" from "better_supabase"."pipeline_stages" s where s."pipeline_id" = v_row."pipeline_id" and s."category"::text = 'unstarted' and s."archived_at" is null order by s."rank" collate "C", s."id" limit 1)
    else (select s."id" from "better_supabase"."pipeline_stages" s where s."pipeline_id" = v_row."pipeline_id" and s."category"::text = 'canceled' and s."archived_at" is null order by s."rank" collate "C", s."id" limit 1) end);
  if v_stage is null then
    raise exception 'the task''s pipeline has no stage for this outcome; pass a stage' using errcode = '22023', hint = 'TASK_STAGE_REQUIRED';
  end if;
  perform set_config('bsb.close_note', coalesce(v_note, ''), true);
  perform set_config('bsb.close_by', coalesce(auth.uid()::text, ''), true);
  begin
    if close_task.outcome = 'failed' then
      begin
        update "better_supabase"."tasks" x set "stage_id" = v_stage, "close_reason" = better_supabase.as_column_type('failed', (null::"better_supabase"."tasks")."close_reason") where x."id" = v_row."id";
      exception when check_violation or invalid_text_representation then
        update "better_supabase"."tasks" x set "stage_id" = v_stage where x."id" = v_row."id";
      end;
    else
      update "better_supabase"."tasks" x set "stage_id" = v_stage where x."id" = v_row."id";
    end if;
  exception when check_violation or foreign_key_violation then
    raise exception 'the stage can''t be used for this task' using errcode = '22023', hint = 'TASK_ATTRS_INVALID';
  end;
  perform set_config('bsb.close_note', '', true);
  select * into v_row from "better_supabase"."tasks" x where x."id" = v_row."id";
  if close_task.outcome = 'failed' then
    null;
  end if;
  return (select to_jsonb(x) || jsonb_build_object('number', x."number"::text) || jsonb_build_object('assignees', coalesce((select jsonb_agg(ra."user_id" order by ra."created_at", ra."user_id") from "better_supabase"."task_assignees" ra where ra."task_id" = x."id"), '[]'::jsonb)) || jsonb_build_object('checklist', (select jsonb_build_object('total', count(*), 'done', count(*) filter (where rk."done")) from "better_supabase"."task_checklist_items" rk where rk."task_id" = x."id")) || jsonb_build_object('claim', "better_supabase"."task_claim"(x."id")) from "better_supabase"."tasks" x where x."id" = v_row."id");
end;
$$;
revoke execute on function "better_supabase"."close_task"(uuid, text, text, uuid) from public, anon;
grant execute on function "better_supabase"."close_task"(uuid, text, text, uuid) to authenticated, service_role;



-- The stages a task has been in, oldest first, with the seconds spent in each.
-- The current stage is open: exitedAt is null and seconds run to now.
create or replace function "better_supabase"."task_stage_times"(task uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return (select coalesce(jsonb_agg(jsonb_build_object(
    'stageId', h."to_stage_id", 'stageName', h."stage_name", 'category', h."category"::text,
    'enteredAt', h."entered_at", 'exitedAt', h."exited_at",
    'seconds', round(extract(epoch from (coalesce(h."exited_at", now()) - h."entered_at")))::bigint
  ) order by h."entered_at"), '[]'::jsonb)
  from "better_supabase"."pipeline_stage_history" h
  join "better_supabase"."tasks" x on x."id"::text = h."subject_id" and x."tenant_id" = h."tenant_id"
  where x."id" = task_stage_times.task and h."subject_type" = 'task'
    and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'tasks.read'), false)));
end;
$$;
revoke execute on function "better_supabase"."task_stage_times"(uuid) from public, anon;
grant execute on function "better_supabase"."task_stage_times"(uuid) to authenticated, service_role;

-- Tells tasks:<tenant> that a task or its claim changed. The payload carries
-- ids only; readers fetch the rows through the API.
create or replace function "better_supabase"."tasks_changed"()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant text;
  v_task uuid;
begin
  if tg_op = 'DELETE' then
    v_tenant := old."tenant_id"::text;
    v_task := old."id";
  else
    v_tenant := new."tenant_id"::text;
    v_task := new."id";
  end if;
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(jsonb_build_object('id', v_task, 'change', lower(tg_op), 'table', tg_table_name), 'changed', 'tasks:' || v_tenant, true);
  end if;
  return null;
end;
$$;
revoke execute on function "better_supabase"."tasks_changed"() from public, anon, authenticated;
create trigger "bsb_tasks_changed"
  after insert or update or delete on "better_supabase"."tasks"
  for each row execute function "better_supabase"."tasks_changed"();
create or replace function "better_supabase"."task_claims_changed"()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant text;
  v_task uuid;
begin
  if tg_op = 'DELETE' then
    v_tenant := old."tenant_id"::text;
    v_task := old."task_id";
  else
    v_tenant := new."tenant_id"::text;
    v_task := new."task_id";
  end if;
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(jsonb_build_object('id', v_task, 'change', lower(tg_op), 'table', tg_table_name), 'changed', 'tasks:' || v_tenant, true);
  end if;
  return null;
end;
$$;
revoke execute on function "better_supabase"."task_claims_changed"() from public, anon, authenticated;
create trigger "bsb_task_claims_changed"
  after insert or update or delete on "better_supabase"."task_claims"
  for each row execute function "better_supabase"."task_claims_changed"();

-- Members join tasks:{tenant}.
create policy bsb_tasks_receive on realtime.messages
  for select to authenticated
  using (realtime.messages.extension = 'broadcast'
        and (select realtime.topic()) like 'tasks:%'
        and substr((select realtime.topic()), 7) in (select x::text from better_supabase.tenant_ids_with('tasks.read') x));

-- Tenant isolation (ADR 0099): permissive policies combine with or, so one
-- the app adds would widen the block's. These restrictive policies keep each
-- table to the caller's organizations and what the block's policies grant.
